90	pub open spec fn valid_cols_src(cols: &Cols_src) -> bool {
91	    cols.n as int <= ROW_CAP_src
92	    && cols.bucket@.len() == cols.n as int
93	    && forall|i: int| 0 <= i < cols.n as int ==> cols.bucket@[i] as int >= 0 && cols.bucket@[i] as int <= 63
94	}
