96	pub proof fn lemma_index_key_below_cap(cols: &Cols_src, i: int)
97	    requires
98	        valid_cols_src(cols),
99	        0 <= i < cols.n as int,
100	    ensures
101	        0 <= cols.bucket@[i] as int,
102	        (cols.bucket@[i] as int) < (KEY_CAP_src_bucket as int),
