107	pub open spec fn group_count(keys: Seq<u64>, i: int, k: u64) -> int
108	    decreases keys.len() - i
109	{
110	    if i < 0 || i >= keys.len() {
111	        0
112	    } else if keys[i] == k {
113	        1 + group_count(keys, i + 1, k)
114	    } else {
115	        group_count(keys, i + 1, k)
116	    }
117	}
118	
119	pub proof fn lemma_group_count_le_suffix(keys: Seq<u64>, i: int, k: u64)
120	    requires
121	        0 <= i <= keys.len(),
122	    ensures
123	        0 <= group_count(keys, i, k) <= keys.len() - i,
124	    decreases keys.len() - i,
125	{
126	    if i < keys.len() {
127	        lemma_group_count_le_suffix(keys, i + 1, k);
128	    }
129	}
130	
131	pub proof fn lemma_group_count_witness(keys: Seq<u64>, i: int, k: u64)
132	    requires
133	        0 <= i <= keys.len(),
134	    ensures
135	        group_count(keys, i, k) > 0 <==> (exists|j: int| i <= j < keys.len() && keys[j] == k),
136	    decreases keys.len() - i,
137	{
138	    if i >= keys.len() {
139	        assert(group_count(keys, i, k) == 0);
140	        assert(forall|j: int| i <= j < keys.len() ==> !(#[trigger] keys[j] == k));
141	    } else {
142	        lemma_group_count_witness(keys, i + 1, k);
143	        if keys[i] == k {
144	            lemma_group_count_le_suffix(keys, i + 1, k);
145	            assert(group_count(keys, i, k) == 1 + group_count(keys, i + 1, k));
146	            assert(group_count(keys, i + 1, k) >= 0);
147	            assert(group_count(keys, i, k) > 0);
148	            assert(exists|j: int| i <= j < keys.len() && keys[j] == k) by {
149	                assert(keys[i] == k);
150	            };
151	        } else {
152	            assert(keys[i] != k);
153	            assert(group_count(keys, i, k) == group_count(keys, i + 1, k));
154	            if group_count(keys, i + 1, k) > 0 {
155	                let j = choose|j: int| i + 1 <= j < keys.len() && keys[j] == k;
156	                assert(i <= j < keys.len() && keys[j] == k);
157	            }
158	            if exists|j: int| i <= j < keys.len() && keys[j] == k {
159	                let j = choose|j: int| i <= j < keys.len() && keys[j] == k;
160	                assert(j != i);
161	                assert(i + 1 <= j < keys.len() && keys[j] == k);
162	                assert(group_count(keys, i + 1, k) > 0);
163	            }
164	        }
165	    }
166	}
