168	pub proof fn lemma_dense_count_map(
169	    keys: Seq<u64>,
170	    counts: Seq<u64>,
171	    map: Map<u64, u64>,
172	    key_cap: int,
173	)
174	    requires
175	        0 <= key_cap,
176	        counts.len() == key_cap,
177	        forall|j: int| 0 <= j < keys.len() ==> {
178	            &&& 0 <= (#[trigger] keys[j] as int)
179	            &&& (keys[j] as int) < key_cap
180	        },
181	        forall|kk: int| 0 <= kk < key_cap ==> counts[kk] as int == group_count(keys, 0, kk as u64),
182	        forall|k: u64| #[trigger] map.contains_key(k) ==> {
183	            &&& (k as int) < key_cap
184	            &&& map[k] == counts[k as int]
185	            &&& counts[k as int] > 0
186	        },
187	        forall|kk: int| 0 <= kk < key_cap && counts[kk] > 0 ==> #[trigger] map.contains_key(kk as u64),
188	    ensures
189	        forall|k: u64| #[trigger] map.contains_key(k) <==> (exists|j: int|
190	            0 <= j < keys.len() && keys[j] == k),
191	        forall|k: u64| #[trigger] map.contains_key(k) ==> map[k] as int == group_count(keys, 0, k),
192	{
193	    assert forall|k: u64|
194	        #[trigger] map.contains_key(k) <==> (exists|j: int| 0 <= j < keys.len() && keys[j] == k)
195	    by {
196	        if map.contains_key(k) {
197	            assert(counts[k as int] as int == group_count(keys, 0, k));
198	            assert(counts[k as int] > 0);
199	            lemma_group_count_witness(keys, 0, k);
200	        }
201	        if exists|j: int| 0 <= j < keys.len() && keys[j] == k {
202	            let j = choose|j: int| 0 <= j < keys.len() && keys[j] == k;
203	            assert(keys[j] == k);
204	            assert(0 <= (keys[j] as int) && (keys[j] as int) < key_cap);
205	            assert((k as int) == (keys[j] as int));
206	            lemma_group_count_witness(keys, 0, k);
207	            assert(group_count(keys, 0, k) > 0);
208	            assert(counts[k as int] > 0);
209	            assert(map.contains_key(k));
210	        }
211	    };
212	    assert forall|k: u64|
213	        #[trigger] map.contains_key(k) ==> map[k] as int == group_count(keys, 0, k)
214	    by {
215	        if map.contains_key(k) {
216	            assert(map[k] == counts[k as int]);
217	            assert(counts[k as int] as int == group_count(keys, 0, k));
218	        }
