275	use vstd::std_specs::ops::*;
276	// Host statement of f64 rounding error; the agent must not unfold an f64 add.
277	pub open spec fn abs_real(x: real) -> real {
278	    if x >= 0real { x } else { -x }
279	}
280	
281	pub open spec fn host_f64_sum_error(n_terms: int, mag_cap: int) -> real {
282	    (n_terms as real) * (n_terms as real) * (mag_cap as real) * (1real / 4503599627370496real)
283	}
