285	pub open spec fn real_sum_seq(terms: Seq<f64>) -> real
286	    decreases terms.len()
287	{
288	    if terms.len() == 0 { 0real }
289	    else { (terms[0] as real) + real_sum_seq(terms.skip(1)) }
290	}
