315	pub proof fn lemma_f64_sum_within_eps(
316	    acc: f64,
317	    n_terms: int,
318	    mag_cap: int,
319	    eps: f64,
320	    terms: Seq<f64>,
321	)
322	    requires
323	        n_terms == terms.len() as int,
324	        0 <= n_terms < 0x10_0000_0000_0000int,
325	        0 <= mag_cap,
326	        acc == f64_left_fold(terms),
327	        forall|i: int| 0 <= i < terms.len() ==> {
328	            let r = #[trigger] (terms[i] as real);
329	            let cap = mag_cap as real;
330	            -cap < r && r < cap
331	        },
332	        host_f64_sum_error(n_terms, mag_cap) <= (eps as real),
333	    ensures
334	        abs_real((acc as real) - real_sum_seq(terms)) <= (eps as real),
335	{ }
