use vstd::std_specs::smart_ptrs::*;
use vstd::std_specs::nonzero::*;
use vstd::hash_map::HashMapWithView;
verus! {
pub open spec const ROW_CAP_src: int = 2000000;
pub const KEY_CAP_src_bucket: usize = 64;
broadcast use vstd::std_specs::hash::axiom_u64_obeys_hash_table_key_model;
pub struct Cols_src {
    pub n: usize,
    pub bucket: Vec<u64>,
}

pub open spec fn valid_cols_src(cols: &Cols_src) -> bool {
    cols.n as int <= ROW_CAP_src
    && cols.bucket@.len() == cols.n as int
    && forall|i: int| 0 <= i < cols.n as int ==> cols.bucket@[i] as int >= 0 && cols.bucket@[i] as int <= 63
}

pub proof fn lemma_index_key_below_cap(cols: &Cols_src, i: int)
    requires
        valid_cols_src(cols),
        0 <= i < cols.n as int,
    ensures
        0 <= cols.bucket@[i] as int,
        (cols.bucket@[i] as int) < (KEY_CAP_src_bucket as int),
{
    assert(0 <= cols.bucket@[i] as int && cols.bucket@[i] as int <= 63);
}

pub open spec fn group_count(keys: Seq<u64>, i: int, k: u64) -> int
    decreases keys.len() - i
{
    if i < 0 || i >= keys.len() {
        0
    } else if keys[i] == k {
        1 + group_count(keys, i + 1, k)
    } else {
        group_count(keys, i + 1, k)
    }
}

pub proof fn lemma_group_count_le_suffix(keys: Seq<u64>, i: int, k: u64)
    requires
        0 <= i <= keys.len(),
    ensures
        0 <= group_count(keys, i, k) <= keys.len() - i,
    decreases keys.len() - i,
{
    if i < keys.len() {
        lemma_group_count_le_suffix(keys, i + 1, k);
    }
}

pub proof fn lemma_group_count_witness(keys: Seq<u64>, i: int, k: u64)
    requires
        0 <= i <= keys.len(),
    ensures
        group_count(keys, i, k) > 0 <==> (exists|j: int| i <= j < keys.len() && keys[j] == k),
    decreases keys.len() - i,
{
    if i >= keys.len() {
        assert(group_count(keys, i, k) == 0);
        assert(forall|j: int| i <= j < keys.len() ==> !(#[trigger] keys[j] == k));
    } else {
        lemma_group_count_witness(keys, i + 1, k);
        if keys[i] == k {
            lemma_group_count_le_suffix(keys, i + 1, k);
            assert(group_count(keys, i, k) == 1 + group_count(keys, i + 1, k));
            assert(group_count(keys, i + 1, k) >= 0);
            assert(group_count(keys, i, k) > 0);
            assert(exists|j: int| i <= j < keys.len() && keys[j] == k) by {
                assert(keys[i] == k);
            };
        } else {
            assert(keys[i] != k);
            assert(group_count(keys, i, k) == group_count(keys, i + 1, k));
            if group_count(keys, i + 1, k) > 0 {
                let j = choose|j: int| i + 1 <= j < keys.len() && keys[j] == k;
                assert(i <= j < keys.len() && keys[j] == k);
            }
            if exists|j: int| i <= j < keys.len() && keys[j] == k {
                let j = choose|j: int| i <= j < keys.len() && keys[j] == k;
                assert(j != i);
                assert(i + 1 <= j < keys.len() && keys[j] == k);
                assert(group_count(keys, i + 1, k) > 0);
            }
        }
    }
}

pub proof fn lemma_dense_count_map(
    keys: Seq<u64>,
    counts: Seq<u64>,
    map: Map<u64, u64>,
    key_cap: int,
)
    requires
        0 <= key_cap,
        counts.len() == key_cap,
        forall|j: int| 0 <= j < keys.len() ==> {
            &&& 0 <= (#[trigger] keys[j] as int)
            &&& (keys[j] as int) < key_cap
        },
        forall|kk: int| 0 <= kk < key_cap ==> counts[kk] as int == group_count(keys, 0, kk as u64),
        forall|k: u64| #[trigger] map.contains_key(k) ==> {
            &&& (k as int) < key_cap
            &&& map[k] == counts[k as int]
            &&& counts[k as int] > 0
        },
        forall|kk: int| 0 <= kk < key_cap && counts[kk] > 0 ==> #[trigger] map.contains_key(kk as u64),
    ensures
        forall|k: u64| #[trigger] map.contains_key(k) <==> (exists|j: int|
            0 <= j < keys.len() && keys[j] == k),
        forall|k: u64| #[trigger] map.contains_key(k) ==> map[k] as int == group_count(keys, 0, k),
{
    assert forall|k: u64|
        #[trigger] map.contains_key(k) <==> (exists|j: int| 0 <= j < keys.len() && keys[j] == k)
    by {
        if map.contains_key(k) {
            assert(counts[k as int] as int == group_count(keys, 0, k));
            assert(counts[k as int] > 0);
            lemma_group_count_witness(keys, 0, k);
        }
        if exists|j: int| 0 <= j < keys.len() && keys[j] == k {
            let j = choose|j: int| 0 <= j < keys.len() && keys[j] == k;
            assert(keys[j] == k);
            assert(0 <= (keys[j] as int) && (keys[j] as int) < key_cap);
            assert((k as int) == (keys[j] as int));
            lemma_group_count_witness(keys, 0, k);
            assert(group_count(keys, 0, k) > 0);
            assert(counts[k as int] > 0);
            assert(map.contains_key(k));
        }
    };
    assert forall|k: u64|
